// ─────────────────────────────────────────────
// Code Node: Feature Mapper & Request Builder
// ─────────────────────────────────────────────
// This node:
//   1. Reads incoming JSON from the webhook
//   2. Validates the actor and task fields exist
//   3. Maps/renames incoming keys to the expected feature names
//   4. Builds the exact payload shape that /predict expects
// ─────────────────────────────────────────────

const body = $input.first().json.body || $input.first().json;

// ── Required top-level fields ──────────────────
const actor = body.actor;
const task  = body.task;
const raw   = body.features || body;

if (!actor || !task) {
  throw new Error('Missing required fields: actor and task must be provided.');
}

// ── Feature alias maps (client key → model key) ──
// Add any renamed/aliased features your clients send here.
const ALIAS_MAPS = {
  actor1: {
    // Example: client sends "fuel" but model expects "type_carburant"
    // "fuel": "type_carburant"
  },
  actor2: {
    // Example: client sends "trip_count" but model expects "nb_trajets"
    // "trip_count": "nb_trajets"
  },
  actor3: {
    // Example: client sends "event_type" but model expects "type_incident"
    // "event_type": "type_incident"
  }
};

// Apply alias mapping for the relevant actor
const aliasMap = ALIAS_MAPS[actor] || {};
const features = {};

for (const [key, value] of Object.entries(raw)) {
  // Skip the top-level routing keys if they leaked into features
  if (key === 'actor' || key === 'task') continue;
  const mappedKey = aliasMap[key] !== undefined ? aliasMap[key] : key;
  features[mappedKey] = value;
}

// ── Build final payload ────────────────────────
const payload = { actor, task, features };

return [{ json: { payload, actor, task } }];

// ─────────────────────────────────────────────
// Success path: normalise and forward the response
// ─────────────────────────────────────────────
const resp = $input.first().json.body || $input.first().json;

return [{
  json: {
    status:      resp.status,
    actor:       resp.actor,
    task:        resp.task,
    prediction:  resp.prediction,
    latency_ms:  resp.latency_ms,
    metadata:    resp.metadata || {}
  }
}];

// ─────────────────────────────────────────────
// Error path: extract detail from FastAPI error
// ─────────────────────────────────────────────
const item = $input.first();
const resp = item.json.body || item.json;
const statusCode = item.json.statusCode || 'unknown';

const errorDetail =
  resp.detail ||
  item.error?.message ||
  'Unknown error from ML backend';

const actor = item.json.actor || 'unknown';
const task  = item.json.task  || 'unknown';

// Log to n8n execution output for debugging
console.error(`[ML Gateway Error] actor=${actor} task=${task} status=${statusCode} detail=${errorDetail}`);

return [{
  json: {
    status:     'error',
    actor,
    task,
    http_status: statusCode,
    error:      errorDetail,
    timestamp:  new Date().toISOString()
  }
}];
